# Let's see which class has the most "dedicated" features (high weight + large gap)
fc_w = W['fc.weight']

print("Features dedicated to each class (gap > 0.2):")
class_dedicated = {i: [] for i in range(10)}
for f in range(64):
    sorted_weights, sorted_indices = torch.sort(fc_w[:, f], descending=True)
    gap = sorted_weights[0] - sorted_weights[1]
    if gap > 0.2:
        class_dedicated[sorted_indices[0].item()].append((f, sorted_weights[0].item(), gap))

for c in range(10):
    if class_dedicated[c]:
        print(f"  Class {c} ({CLASSES[c]}): {len(class_dedicated[c])} features")
        for f, w, gap in sorted(class_dedicated[c], key=lambda x: -x[1]):
            print(f"    Feature {f}: weight={w:.4f}, gap={gap:.4f}, bias={W['conv3.bias'][f]:.4f}")

# Also check: for each class, sum of top-k weights
print("\nSum of top-5 FC weights per class:")
for c in range(10):
    top5 = torch.topk(fc_w[c], 5)
    print(f"  Class {c} ({CLASSES[c]}): features {top5.indices.tolist()}, weights {top5.values.tolist()}, sum={top5.values.sum():.4f}")

print("\nSum of all positive FC weights per class:")
for c in range(10):
    pos_sum = fc_w[c][fc_w[c] > 0].sum().item()
    neg_sum = fc_w[c][fc_w[c] < 0].sum().item()
    print(f"  Class {c}: pos_sum={pos_sum:.4f}, neg_sum={neg_sum:.4f}, total={pos_sum+neg_sum:.4f}")
